const prototypeAreaCopy={
  "Company Intelligence":["Company Intel","Research a company, understand the business, and see what matters before applying."],
  "Job Intelligence":["Job Intel","Decide whether a specific opening is real, current, worth the effort, and likely to convert."],
  "Worker Intelligence":["Reviews","First-party candidate and worker experience, structured for job-seeker decisions."],
  "Job-Search Tools":["Tools","Compare paid job-search products and services before spending money."],
  "Interview Prep":["Interview Prep","Turn a job description and company context into practical interview preparation."],
  "Compensation":["Pay","Track compensation signals and changes across the hiring process."],
  "Career Transition":["Career Transition","Translate experience into realistic adjacent roles and industries."],
  "Worker Community":["Community","A worker-first space for company, role, industry, and transition intelligence."]
};

function prototypePlaceholder(feature){
  const demoReady=["Company Overview Dashboard","Company Grade / Summary","Business Stability","Hiring Snapshot","Positive Signals / Risk Flags","Company Deep Dives","Hiring Reality / Ghost-Job Signals","Application Decision Summary","ATS Identification","AI-in-Hiring Indicator","Questions to Ask Employer"];
  if(demoReady.includes(feature.name)) return {label:"Demo available",tone:"demo",value:"Open a demo company above to see this feature with populated research."};
  if(feature.area==="Worker Intelligence"||feature.area==="Worker Community") return {label:"Test data",tone:"test",value:"N/A — waiting for Fly user submissions. The interaction is included for user testing."};
  if(feature.area==="Job-Search Tools") return {label:"Directory shell",tone:"test",value:"N/A — service data is being populated. Profile, outcome and review states are visible for testing."};
  if(feature.area==="Interview Prep") return {label:"Prototype flow",tone:"test",value:"N/A — enter or paste a job description when this workflow is wired to data."};
  if(feature.area==="Career Transition") return {label:"Prototype flow",tone:"test",value:"N/A — results will populate from work history and evidence-backed occupation data."};
  if(feature.area==="Compensation") return {label:"Data pending",tone:"na",value:"N/A — not enough evidence yet. The compensation module remains visible by design."};
  return {label:"Data pending",tone:"na",value:"N/A — not enough evidence yet. Feature retained for the user test."};
}

function buildPrototypeExplorer(){
  const root=document.getElementById("prototypeExplorer");
  if(!root) return;
  const tabs=root.querySelector("#prototypeAreaTabs");
  const panel=root.querySelector("#prototypeAreaPanel");
  const areas=Object.keys(prototypeAreaCopy);

  function renderArea(area){
    tabs.querySelectorAll("button").forEach(b=>b.classList.toggle("active",b.dataset.area===area));
    const [shortLabel,desc]=prototypeAreaCopy[area];
    const list=flyPrototypeFeatures.filter(f=>f.area===area);
    const modules=[...new Set(list.map(f=>f.module))];
    panel.innerHTML=`
      <div class="prototype-area-head">
        <div><p class="eyebrow">User-test build</p><h3>${shortLabel}</h3><p>${desc}</p></div>
        <div class="prototype-count"><strong>${list.length}</strong><span>features visible</span></div>
      </div>
      ${area==="Interview Prep"?`<div class="prototype-input-card"><label>Job link or description</label><textarea placeholder="Paste a job description or job link here to test the interview-prep flow…"></textarea><button type="button" class="prototype-primary">Prep me for this interview</button><small>Prototype interaction — outputs may show N/A until data/logic is connected.</small></div>`:""}
      ${area==="Career Transition"?`<div class="prototype-input-card"><label>Work history / résumé</label><textarea placeholder="Paste work history here to test the career-transition flow…"></textarea><button type="button" class="prototype-primary">Find transition paths</button><small>Prototype interaction — matches remain N/A until evidence/data is connected.</small></div>`:""}
      ${area==="Worker Intelligence"?`<div class="prototype-input-card"><label>Share an experience</label><select><option>Company / candidate experience</option><option>Interview process</option><option>Recruiter / staffing agency</option><option>Application process</option><option>Job-search tool / paid service</option></select><textarea placeholder="Tell Fly what happened…"></textarea><button type="button" class="prototype-primary">Preview submission</button><small>Prototype only — this does not publish a real review.</small></div>`:""}
      <div class="prototype-modules">
        ${modules.map(module=>`<section class="prototype-module"><div class="prototype-module-title"><h4>${module}</h4><span>${list.filter(f=>f.module===module).length} items</span></div><div class="prototype-feature-grid">${list.filter(f=>f.module===module).map(feature=>{const p=prototypePlaceholder(feature);return `<article class="prototype-feature-card" tabindex="0"><div class="prototype-feature-top"><span class="prototype-status ${p.tone}">${p.label}</span><span class="prototype-source">User test</span></div><h5>${feature.name}</h5><p>${p.value}</p><button type="button" class="prototype-link" data-feature="${feature.name.replace(/"/g,"&quot;")}">See how this will work</button></article>`}).join("")}</div></section>`).join("")}
      </div>`;
    panel.querySelectorAll(".prototype-link").forEach(btn=>btn.addEventListener("click",()=>openPrototypeDetail(btn.dataset.feature)));
  }

  areas.forEach((area,i)=>{
    const b=document.createElement("button");
    b.type="button"; b.dataset.area=area; b.textContent=prototypeAreaCopy[area][0];
    b.addEventListener("click",()=>renderArea(area)); tabs.appendChild(b);
  });
  renderArea(areas[0]);
}

function openPrototypeDetail(name){
  const feature=flyPrototypeFeatures.find(f=>f.name===name);
  if(!feature) return;
  const p=prototypePlaceholder(feature);
  const dialog=document.getElementById("prototypeFeatureDialog");
  document.getElementById("prototypeFeatureArea").textContent=feature.area;
  document.getElementById("prototypeFeatureTitle").textContent=feature.name;
  document.getElementById("prototypeFeatureModule").textContent=feature.module;
  document.getElementById("prototypeFeatureValue").textContent=p.value;
  dialog.showModal();
}

document.addEventListener("DOMContentLoaded",buildPrototypeExplorer);
